/*
* Build Generator/optimizer Prompt
* mode: runOnceForEachItem
* Works for iteration 0 (first draft) and >= 1 (optimize using feedback)
*/

const {
  iteration = 0,
  sourcetext = '',
  targetlang = '',
  bestTranslation = '',
  feedbackSummary = '',
  feedbackList = [],
} = $json;

// bullet-point block for later iterations 
const bulletBlock = Array.isArray(feedbackList) && feedbackList.length
  ? feedbackList.map(t => `- ${t}`).join('\n')
  : '- (no detailed feedback yet)';

let prompt;

/* -------------BRANCH A: first ever pass ------------*/ 
if (iteration === 0) {
  prompt = `You are **Translation-Writer-v1** - a professional translator.

=*****************************
INPUT
- source_text: ${sourcetext}
- target_language: ${targetlang}
******************************

TASK
1. Produce a **fluent, idiomatic translation** of source_text into target_language.
2. **Preserve meaning** precisely - no omissions or additions.
3. Mirror the **tone & register** of the original text.
4. Adapt cultural references naturally or clarify if needed.
5. Length <= 120% of the source
6. Output **only** the translated text - no explanations.

Begin your translation now.`;
}  

/* -------------BRANCH B: optimization rounds ----------*/
else {
  prompt = `You are **Translation-Writer-v1** - a professional translator improving a draft.

**********************************
INPUT
- source_text: ${sourcetext}
- target_language: ${targetlang}
- previous_translation: ${bestTranslation}
- evaluator_feedback: ${feedbackSummary}

Extra feedback list:
${bulletBlock}
*********************************

TASK
Apply the feedback to deliver a better translation while following the same rules.
Return **only** the updated translation.`;
}

// Return as a FunctionItem output
return { ...$json, prompt };

const { sourcetext, targetLang, currentTranslation } = $json;

const prompt = `You are a **Translation-Quality-Evaluator**.
Your goal is to judge a machine-generated translation against the rubric below and return a structured JSON report.

******************
INPUTS
  - source_text: ${sourcetext}
  - candidate_translation: ${currentTranslation}
  - target_language: ${targetLang}
******************

RUBRIC (each-category 0-100; higher = better)

1. Accuracy (Adequacy/Fidelity) - Does the meaning match the source exactly?
2. Fluency - Is the translation grammatical and natural for a native speaker?
3. Cultural & stylistic Appropriateness - Are idioms, tone and register correct for the target audience and context?
4. Instruction-Following - Does the translation obey any style/length/format constraints provided?

Aggregate the sub-scores into **overall_score** (weighted: Accuracy 40%, Fluency 30%, Culture 20%, Instructions 10%).
Set **pass** to true when overall_score >= 90.

***********************
OUTPUT FORMAT (STRICT JSON)

{
  "pass": true or false,
  "overall_score": 0–100,
  "scores": {
    "accuracy": 0–100,
    "fluency": 0–100,
    "culture": 0–100,
    "instructions": 0–100
  },
  "feedback": {
    "summary": "One-sentence headline about the translation quality",
    "detail": [
      "Concrete, numbered suggestions for improvement — max 4 items"
    ]
  }
}

Rules:
  * Produce only valid JSON — no code fences, comments, or extra keys.
  * Feedback must be actionable (e.g., "Replace literal word-order with natural target-language syntax", not "bad translation").
  * Never rewrite the translation yourself; critique only.
  * If overall_score < 90, 'pass' **must** be false.

End of prompt.`;

return { prompt };

