// ------- Update State --------
const {

  iteration  = $('build generator/ optimizer prompt').item.json["iteration "],
  bestScore = $('build generator/ optimizer prompt').item.json.bestScore,
  bestTranslation = $('build generator/ optimizer prompt').item.json.bestTranslation,
  sourcetext = $('build generator/ optimizer prompt').item.json.sourcetext,
  targetlang = $('build generator/ optimizer prompt').item.json.targetlang,
  overallScore = $json.output.overall_score,
  pass = $json.output.pass,
  feedbackSummary = $json.output.feedback.summary,
  feedbackList = $json.output.feedback.detail,
  currentTranslation = $('Generator/Optimizer').item.json.text
} = $json;

// Decide if this round is better
const isBetter = overallScore > bestScore;

return {
  iteration: iteration + 1,
  bestScore: isBetter ? overallScore : bestScore,
  bestTranslation: isBetter ? currentTranslation : bestTranslation,
  pass,
  sourcetext,
  targetlang,
  currentTranslation,
  feedbackSummary,
  feedbackList, // accumulate
};
